package com.smartmerchant.saas.gateway;
import org.springframework.beans.factory.annotation.Value; import org.springframework.cloud.gateway.filter.GatewayFilterChain; import org.springframework.cloud.gateway.filter.GlobalFilter; import org.springframework.core.Ordered; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.HexFormat;
@Component public class TrustedContextGlobalFilter implements GlobalFilter, Ordered {
 private final byte[] signingKey; public TrustedContextGlobalFilter(@Value("${saas.security.internal-signing-key}")String key){this.signingKey=key.getBytes(StandardCharsets.UTF_8);}
 @Override public Mono<Void> filter(ServerWebExchange exchange,GatewayFilterChain chain){return exchange.getPrincipal().defaultIfEmpty(() -> "anonymous").flatMap(principal->{if(principal instanceof JwtAuthenticationToken auth){var jwt=auth.getToken();Object tenantClaim=jwt.getClaim("tenant_id");Object userClaim=jwt.getClaim("user_id");String tenant=String.valueOf(tenantClaim);String user=String.valueOf(userClaim);String jti=jwt.getId();String value=tenant+"|"+user+"|"+jti;var request=exchange.getRequest().mutate().headers(h->{h.remove("X-Tenant-Id");h.remove("X-User-Id");h.remove("X-Internal-Caller");h.remove("X-Internal-Signature");h.set("X-Tenant-Id",tenant);h.set("X-User-Id",user);h.set("X-Internal-Caller","saas-gateway");h.set("X-Internal-Signature",sign(value));}).build();return chain.filter(exchange.mutate().request(request).build());}return chain.filter(exchange);});}
 private String sign(String value){try{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(signingKey,"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Override public int getOrder(){return 10000;}
}
